#pragma once

// Simulation-only demand/refill accounting at the same core edge as the RTL.
struct TextureRefillStats {
    struct PhysicalLine {
        std::uint32_t tag = 0;
        std::uint8_t valid_words = 0;
        std::array<unsigned, 8> descriptor{};
    };
    std::array<PhysicalLine, 64> shadow{};
    std::array<std::uint64_t, 4> state_clocks{};
    std::array<std::uint64_t, 9> lengths{}, split_lengths{};
    std::uint64_t requests = 0, replies = 0, hits = 0, misses = 0, configurations = 0;
    std::uint64_t changed_descriptors = 0, flushes = 0, published = 0;
    std::uint64_t shadow_hits = 0, recovered_real_misses = 0, recovered_old_descriptor = 0;
    std::uint64_t response_wait = 0, response_backpressure = 0, response_words = 0;
    std::uint64_t cache_write_edges = 0, texture_raster_stall = 0, raster_stall_during_miss = 0;
    std::uint64_t other_pending_during_tex_stream = 0;
    std::uint64_t miss_to_cmd_total = 0, cmd_to_first_total = 0;
    std::uint64_t first_to_last_total = 0, last_to_publish_total = 0;
    std::uint64_t miss_at = 0, command_at = 0, first_at = 0, last_at = 0;
    unsigned descriptor = 0, accepted = 0, announced_words = 0;
    bool outstanding = false;

    void shadow_demand(std::uint32_t address, std::uint32_t base, std::uint32_t extent,
                       bool real_miss) {
        const auto physical_tag = address >> 5;
        const auto word = (address >> 2) & 7u;
        auto& line = shadow[physical_tag & 63u];
        const bool hit = line.tag == physical_tag && (line.valid_words & (1u << word));
        if (hit) {
            ++shadow_hits;
            if (real_miss) {
                ++recovered_real_misses;
                if (line.descriptor[word] != descriptor) ++recovered_old_descriptor;
            }
            return;
        }
        if (line.tag != physical_tag) {
            line = {};
            line.tag = physical_tag;
        }
        const auto line_base = physical_tag << 5;
        for (unsigned i = 0; i < 8; ++i) {
            const auto byte = line_base + i * 4;
            if (byte >= base && byte + 4 <= base + extent) {
                line.valid_words |= 1u << i;
                line.descriptor[i] = descriptor;
            }
        }
    }

    void sample(const Vnano_gpu_core___024root& top, std::uint64_t cycle) {
#define CORE(name) top.nano_gpu_core__DOT__##name
#define CACHE(name) top.nano_gpu_core__DOT__texture_cache__DOT__##name
#define FRAGMENT(name) top.nano_gpu_core__DOT__tile_renderer__DOT__fragments__DOT__##name
#define TILE(name) top.nano_gpu_core__DOT__tile_renderer__DOT__##name
#define MEMORY(name) top.nano_gpu_core__DOT__memory_service__DOT__##name
        const auto state = CACHE(state);
        ++state_clocks.at(state);
        requests += FRAGMENT(texture_accept);
        replies += FRAGMENT(texture_response);
        cache_write_edges += CACHE(cache_ram__DOT__we);
        if (CORE(tex_flush)) {
            ++flushes;
            shadow.fill({});
        }
        if (CORE(tex_cfg_ready) && CORE(tex_cfg_valid)) {
            ++configurations;
            if (CACHE(cfg_changed)) {
                ++changed_descriptors;
                ++descriptor;
            }
        }
        if (state == 0 && CACHE(output_advance) && CACHE(linear_valid)) {
            const bool real_miss = !CACHE(line_hit);
            shadow_demand(CACHE(base) + 2 * CACHE(linear_address), CACHE(base),
                          CACHE(extent), real_miss);
            if (real_miss) {
                if (outstanding) throw std::logic_error("Texture profile overlapping miss");
                ++misses;
                outstanding = true;
                miss_at = cycle;
                accepted = 0;
                announced_words = 0;
            } else ++hits;
        }
        if (CORE(tex_cmd_valid) && (CORE(mem_cmd_ready) & 16u)) {
            if (!outstanding || announced_words)
                throw std::logic_error("Texture profile unpaired command");
            announced_words = CACHE(bounded_read_words);
            ++lengths.at(announced_words);
            const unsigned first_column_word = (CORE(tex_cmd_addr) >> 2) & 7u;
            if (first_column_word + announced_words > 8) ++split_lengths.at(announced_words);
            command_at = cycle;
            miss_to_cmd_total += cycle - miss_at;
        }
        if (state == 2) {
            const bool read_valid = MEMORY(r_valid) & 16u;
            const bool read_ready = CORE(tex_r_ready);
            response_wait += read_ready && !read_valid;
            response_backpressure += read_valid && !read_ready;
            if (read_ready && read_valid) {
                if (!outstanding || !announced_words)
                    throw std::logic_error("Texture profile response without command");
                if (!accepted) {
                    first_at = cycle;
                    cmd_to_first_total += cycle - command_at;
                }
                ++response_words;
                if (++accepted == announced_words) {
                    last_at = cycle;
                    first_to_last_total += cycle - first_at;
                }
            }
        }
        if (CACHE(tag_ram__DOT__we)) {
            if (!outstanding || !announced_words || accepted != announced_words)
                throw std::logic_error("Texture profile tag published before complete refill");
            ++published;
            last_to_publish_total += cycle - last_at;
            outstanding = false;
        }
        if (TILE(state) == 8 && TILE(inside_sample) && TILE(need_texture) &&
            !TILE(fragment_ready)) {
            ++texture_raster_stall;
            raster_stall_during_miss += state != 0;
        }
        other_pending_during_tex_stream += MEMORY(read_stream_active) &&
            MEMORY(stream_owner) == 4 && (CORE(mem_cmd_valid) & 47u);
#undef MEMORY
#undef TILE
#undef FRAGMENT
#undef CACHE
#undef CORE
    }

    void print(std::ostream& output, const char* name, std::uint64_t cycles,
               unsigned ram_writes_per_sdram_word) const {
        if (outstanding || misses != published || requests != replies ||
            hits != requests || cache_write_edges < response_words * ram_writes_per_sdram_word)
            throw std::logic_error("Texture profile incomplete demand/refill sequence");
        const auto emit = [&](const char* key, std::uint64_t value) {
            output << ",\"" << key << "\":" << value;
        };
        const auto array = [&](const char* key, const auto& values) {
            output << ",\"" << key << "\":[";
            for (unsigned i = 0; i < values.size(); ++i) {
                if (i) output << ',';
                output << values[i];
            }
            output << ']';
        };
        output << "{\"case\":\"" << name << "\"";
        emit("cycles", cycles); emit("accepted_texel_requests", requests);
        emit("returned_texels", replies); emit("hit_deliveries_including_refills", hits);
        emit("demand_refills", misses); emit("descriptors_accepted", configurations);
        emit("descriptor_changes", changed_descriptors); emit("pass_flushes", flushes);
        emit("shadow_hits", shadow_hits); emit("shadow_hits_on_real_misses", recovered_real_misses);
        emit("shadow_hits_from_earlier_descriptor", recovered_old_descriptor);
        emit("presented_response_cycles_blocked_by_cache", response_backpressure);
        emit("response_cycles_waiting_for_service", response_wait);
        emit("response_words", response_words); emit("data_ram_write_edges", cache_write_edges);
        emit("padding_write_edges", cache_write_edges - response_words * ram_writes_per_sdram_word);
        emit("raster_texture_stall", texture_raster_stall);
        emit("raster_texture_stall_during_miss", raster_stall_during_miss);
        emit("other_commands_pending_during_texture_stream", other_pending_during_tex_stream);
        emit("miss_to_command_clocks_sum", miss_to_cmd_total);
        emit("command_to_first_response_clocks_sum", cmd_to_first_total);
        emit("first_to_last_response_clocks_sum", first_to_last_total);
        emit("last_response_to_tag_clocks_sum", last_to_publish_total);
        array("cache_state_clocks", state_clocks);
        array("refills_by_words", lengths); array("split_refills_by_words", split_lengths);
        output << "}\n";
        output.flush();
    }
};
